WITH flattened_attrs AS (SELECT id, service, host, payload_json, COALESCE(context['trace'], 'none') AS trace_or_default, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration AS duration_sec FROM app_logs) SELECT *, AVG(duration_sec) OVER w_running AS duration_sec_avg_6, SUM(duration_sec) OVER (PARTITION BY service ORDER BY duration_sec, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_duration_sec FROM flattened_attrs WINDOW w_running AS (ORDER BY duration_sec, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW);
